// Writes lib/config/firebase_local.dart, the gitignored file holding this
// install's Firebase identifiers.
//
// Why a generated file and not --dart-define: a bare `flutter build apk`
// (phone-deploy, CI) silently compiles empty defines into a sign-in button
// that can never work. A missing generated file instead fails the compile
// with an error naming this tool. The values are public-by-design (they ship
// in every APK) but DOCS-contract §10 keeps them out of this public repo.
//
// Usage (from app/):
//   dart run tool/write_firebase_config.dart            # from ~/.config
//   dart run tool/write_firebase_config.dart --placeholder   # CI: empty values
//
// Sources, in order: ~/.config/crdt-sync/firebase.json (apiKey, databaseUrl,
// uid); the Google *Web* OAuth client id from $TUTOR_GOOGLE_SERVER_CLIENT_ID,
// else that file's `webClientId`, else todo's committed kServerClientId.
import 'dart:convert';
import 'dart:io';

const _out = 'lib/config/firebase_local.dart';

void main(List<String> args) {
  final placeholder = args.contains('--placeholder');
  final values = placeholder ? FirebaseLocal.empty : _fromConfig();
  File(_out).writeAsStringSync(render(values));
  stdout.writeln(
    'wrote $_out (${placeholder ? 'placeholder' : 'from ~/.config'})',
  );
}

/// The four identifiers the app needs at runtime.
class FirebaseLocal {
  /// Creates the identifier set.
  const new({
    required this.apiKey,
    required this.databaseUrl,
    required this.syncUid,
    required this.serverClientId,
  });

  /// All-empty values: the app shows "not configured" instead of signing in.
  static const empty = FirebaseLocal(
    apiKey: '',
    databaseUrl: '',
    syncUid: '',
    serverClientId: '',
  );

  /// Web API key of the kuhy-syncs project.
  final String apiKey;

  /// Regional RTDB URL.
  final String databaseUrl;

  /// The uid the sync account resolves to (the expectedUid guard).
  final String syncUid;

  /// Google Web OAuth client id (token audience).
  final String serverClientId;
}

/// Parses `firebase.json` and picks the client id per the order above.
FirebaseLocal parse(
  String firebaseJson, {
  String? envClientId,
  String? todoSource,
}) {
  final json = jsonDecode(firebaseJson) as Map<String, dynamic>;
  String need(String key) {
    final value = json[key];
    if (value is! String || value.isEmpty) {
      throw FormatException('firebase.json has no "$key"');
    }
    return value;
  }

  final match = RegExp(
    r"kServerClientId =\s*'([^']+)'",
  ).firstMatch(todoSource ?? '');
  final clientId = [
    envClientId,
    json['webClientId'] as String?,
    match?.group(1),
  ].firstWhere((v) => v != null && v.isNotEmpty, orElse: () => '')!;
  return FirebaseLocal(
    apiKey: need('apiKey'),
    databaseUrl: need('databaseUrl'),
    syncUid: need('uid'),
    serverClientId: clientId,
  );
}

/// The Dart source written to [_out].
String render(FirebaseLocal v) =>
    '''
// GENERATED by tool/write_firebase_config.dart. Gitignored: never commit.
// This repo is public (DOCS-contract §10).

/// Web API key of the kuhy-syncs project.
const kFirebaseApiKey = ${_quote(v.apiKey)};

/// Regional RTDB URL.
const kFirebaseDatabaseUrl = ${_quote(v.databaseUrl)};

/// The uid the sync account must resolve to (expectedUid guard).
const kFirebaseSyncUid = ${_quote(v.syncUid)};

/// Google Web OAuth client id, the ID-token audience.
const kGoogleServerClientId = ${_quote(v.serverClientId)};
''';

/// A single-quoted Dart literal for [s].
String _quote(String s) {
  final escaped = s
      .replaceAll(r'\', r'\\')
      .replaceAll("'", r"\'")
      .replaceAll(r'$', r'\$');
  return "'$escaped'";
}

FirebaseLocal _fromConfig() {
  final home = Platform.environment['HOME'] ?? '';
  final todo = File('$home/src/todo/lib/sync/google_sign_in_backend.dart');
  return parse(
    File('$home/.config/crdt-sync/firebase.json').readAsStringSync(),
    envClientId: Platform.environment['TUTOR_GOOGLE_SERVER_CLIENT_ID'],
    todoSource: todo.existsSync() ? todo.readAsStringSync() : null,
  );
}
